#!/bin/bash
c=$2; for i in 1 2 3 4; do n=$(( c>8?8:c )); m[$i]=$((256-2**(8-n))); ((c-=n)); done; IFS=. read -r a b c d <<< "$1"; n1=$((a&m[1])); n2=$((b&m[2])); n3=$((c&m[3])); n4=$((d&m[4])); b1=$((n1|(~m[1]&255))); b2=$((n2|(~m[2]&255))); b3=$((n3|(~m[3]&255))); b4=$((n4|(~m[4]&255))); printf "%d.%d.%d.%d - %d.%d.%d.%d\n" $n1 $n2 $n3 $((n4+1)) $b1 $b2 $b3 $((b4-1))
